import { history } from './history';
import qs from 'query-string';


// 判断是否为函数类型
function isFunction(val): boolean {
    return typeof val === 'function';
}

// 判断是否为promise 类型
function isPromise(val): boolean {
    return typeof val === 'object' && isFunction(val.then) && isFunction(val.catch) && isFunction(val.finally);
}


/**
 * 获取url中所有参数
 * @defaultValue object 默认参数
 */
function getAllQueryParam(url?: string): Record<string, any>{
    let path = url || window.location.href.replace('#/','&=');
    const result = Object.create(null);
    if (!path || path.indexOf('?') === -1) return result;
    const paths = path.split('?');
    paths.shift()
    for (const pathStr of paths) {
        const array = pathStr.split(/[&=]/);
        for (let i = 0; i < array.length; i += 2) {
            result[array[i]] = decodeURIComponent(array[i + 1]);
        }
    }
    return result;
}


export default {
    history,
    isPromise,
    getAllQueryParam,
}
